package net.bible.service.cloudsync.ios

import kotlin.io.encoding.Base64
import kotlin.test.*
import net.bible.service.cloudsync.host.certificateDetails

class CertificateDetailsTest {
    @Test fun realCertificateIssuerAndValidity() {
        val info = assertNotNull(certificateDetails(Base64.decode(ISRG_X1)))
        assertEquals("C=US, O=Internet Security Research Group, CN=ISRG Root X1", info.issuer)
        assertEquals(1433415878000L, info.notBefore)
        assertEquals(2064567878000L, info.notAfter)
    }
    @Test fun malformedCertificateCannotProduceInventedDetails() {
        for (bytes in listOf(byteArrayOf(), byteArrayOf(0x30, 0x7f), Base64.decode(ISRG_X1).copyOf(100))) {
            assertNull(certificateDetails(bytes))
        }
    }
    companion object {
        // Public ISRG Root X1 certificate, /etc/ssl/certs; dates independently checked with openssl x509.
        const val ISRG_X1 = ""
    }
}
